import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
compact_whitespace = target.compact_whitespace


def test_strips_and_preserves_order():
    lines = ["  hello  ", "\tworld\n", "", "   ", "  last "]
    assert compact_whitespace(lines) == ["hello", "world", "last"]


def test_omits_whitespace_only_lines():
    assert compact_whitespace(["", "   ", "\t\n", "\n"]) == []


def test_empty_input():
    assert compact_whitespace([]) == []


def test_no_whitespace_lines_unchanged():
    lines = ["a", "bb", "ccc"]
    assert compact_whitespace(lines) == ["a", "bb", "ccc"]


def test_internal_whitespace_kept():
    assert compact_whitespace(["  a b c  "]) == ["a b c"]


def test_all_stripped_lines_kept_in_order():
    lines = [" z ", "  a  ", " m "]
    assert compact_whitespace(lines) == ["z", "a", "m"]


def test_mixed_several_lines():
    lines = ["   one", "two\t", "   ", " three  "]
    assert compact_whitespace(lines) == ["one", "two", "three"]
