{"filename": "test_merge_inventory.py", "content": "import os
import importlib.util
import copy
import pytest

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
merge_inventory = target.merge_inventory


def test_both_empty():
    assert merge_inventory({}, {}) == {}


def test_only_base():
    assert merge_inventory({'a': 5}, {}) == {'a': 5}


def test_only_incoming():
    assert merge_inventory({}, {'b': 3}) == {'b': 3}


def test_disjoint_keys():
    assert merge_inventory({'a': 1}, {'b': 2}) == {'a': 1, 'b': 2}


def test_matching_sku_counts_added():
    assert merge_inventory({'a': 1, 'b': 2}, {'a': 10, 'c': 5}) == {'a': 11, 'b': 2, 'c': 5}


def test_multiple_matching_keys():
    assert merge_inventory({'x': 2, 'y': 3, 'z': 4}, {'x': 8, 'y': 100}) == {'x': 10, 'y': 103, 'z': 4}


def test_zero_counts_preserved():
    assert merge_inventory({'a': 0}, {'a': 0}) == {'a': 0}
    assert merge_inventory({'a': 0}, {'b': 7}) == {'a': 0, 'b': 7}


def test_returns_new_dict_and_does_not_mutate_inputs():
    base = {'a': 1, 'b': 2}
    incoming = {'a': 5, 'c': 9}
    base_snapshot = copy.deepcopy(base)
    incoming_snapshot = copy.deepcopy(incoming)
    result = merge_inventory(base, incoming)
    assert base == base_snapshot, "base was mutated"
    assert incoming == incoming_snapshot, "incoming was mutated"
    assert result is not base, "result should be a new dict, not base"
    assert result is not incoming, "result should be a new dict, not incoming"
    assert result == {'a': 6, 'b': 2, 'c': 9}


def test_same_object_passed_for_both_inputs():
    d = {'a': 1}
