def test_returns_n_largest_in_descending_order():
    assert top_n([3, 1, 4, 1, 5, 9, 2, 6], 3) == [9, 6, 5]


def test_n_larger_than_input_returns_all_descending():
    assert top_n([3, 1, 4], 10) == [4, 3, 1]


def test_n_equals_input_size_returns_all_descending():
    assert top_n([5, 2, 8, 1], 4) == [8, 5, 2, 1]


