    assert top_n([42], 1) == [42]


def test_n_zero_with_empty_list():
    assert top_n([], 0) == []


def test_n_positive_with_empty_list():
    assert top_n([], 5) == []


def test_negative_values():
    assert top_n([-1, -5, -3, -2], 2) == [-1, -2]


def test_all_same_values():
